# Since we don't have the exact library, I'll create a simple implementation
# to demonstrate the approach

def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal change from s_in to s_out."""
    # Simple approach: find first differing character
    min_len = min(len(s_in), len(s_out))

    # Look for character changes
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if it's a substitution
            old_char = s_in[i]
            new_char = s_out[i]
            return (old_char, new_char, i)

    # If we get here, it's a length change or we need to handle differently
    if len(s_in) < len(s_out):
        # Insertion case - find insertion point
        for i in range(len(s_in)):
            if s_in[i] != s_out[i]:
                return (s_in[i], s_out[i], i)
        # Insert at end
        return (s_in[-1] if s_in else "", s_out[len(s_in):len(s_in)+1], len(s_in))
    elif len(s_in) > len(s_out):
        # Deletion case
        for i in range(len(s_out)):
            if s_in[i] != s_out[i]:
                return (s_in[i], s_out[i], i)
        # Delete at end  
        return (s_in[len(s_out)], "", len(s_out))

    return ("", "", -1)

def propose_rule_candidates(s_in, s_out):
    """Propose potential rule candidates."""
    # Simple approach: look at what changes and propose replacements
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    # Return specific replacement
    if old_sub and new_sub:
        return [(old_sub, new_sub)]
    elif old_sub and not new_sub:
        # Deletion case
        return [(old_sub, "")]
    else:
        # Might be a more complex pattern - return some generalizations
        return [("x", "y")]  # placeholder

def apply_rules(strings, rules):
    """Apply a sequence of rules to strings."""
    result = strings[:]
    for pattern, replacement in rules:
        result = [s.replace(pattern, replacement) for s in result]
    return result

def score_rules(inputs, outputs, rules):
    """Score how well rules match the inputs/outputs."""
    results = apply_rules(inputs, rules)
    correct = sum(1 for i, r in enumerate(results) if r == outputs[i])
    return correct / len(inputs)

def find_over_applications(inputs, outputs, rules):
    """Find examples where rules over-apply."""
    results = apply_rules(inputs, rules)
    over_apps = []
    for i, (inp, outp, res) in enumerate(zip(inputs, outputs, results)):
        if res != outp and inp != outp:  # If result doesn't match expected and input/output are different
            over_apps.append((i, inp, res))
    return over_apps

